SELECT t.id as thread_id, -- Return timestamps from the chosen messages directly COALESCE(earliest_msg.sent_at, earliest_msg.updated_at) as "first_message_ts!", COALESCE(latest_msg.sent_at, latest_msg.updated_at) as "last_message_ts!", -- Last time user viewed this thread uh.updated_at as "viewed_at?", latest_msg.snippet, earliest_msg.subject as "subject?", l.macro_id, t.link_id, latest_msg.sender as "sender?", latest_msg.pretty_sender as "pretty_sender?", latest_msg.trash_label as trash_label, ( SELECT m_latest.is_draft FROM email_messages m_latest WHERE m_latest.thread_id = t.id AND m_latest.link_id = t.link_id AND NOT (m_latest.is_draft AND COALESCE((m_latest.mailbox_state->>'provider_missing')::boolean, false)) ORDER BY m_latest.internal_date_ts DESC NULLS LAST LIMIT 1 ) AS "is_draft!", t.is_read, t.inbox_visible, -- Gmail's IMPORTANT label — a different notion from the -- Importance filter / email_threads.is_signal heuristic. ( SELECT EXISTS ( SELECT 1 FROM email_messages m_imp JOIN email_message_labels ml ON m_imp.id = ml.message_id JOIN email_labels l ON ml.label_id = l.id WHERE m_imp.thread_id = t.id AND l.link_id = t.link_id AND l.name = 'IMPORTANT' ) ) AS "is_important!" FROM email_threads t LEFT JOIN email_user_history uh ON uh.thread_id = t.id AND uh.link_id = t.link_id LEFT JOIN email_links l ON l.id = t.link_id -- LATERAL join for LATEST message -- JOIN (Inner) acts as a filter to ensure we only return threads that actually have messages JOIN LATERAL ( SELECT m2.snippet, m2.sent_at, m2.updated_at, c.email_address as sender, COALESCE(c.name, c.email_address) as pretty_sender, EXISTS( SELECT 1 FROM email_message_labels eml JOIN email_labels el ON el.id = eml.label_id WHERE eml.message_id = m2.id AND el.provider_label_id = 'TRASH' ) as trash_label FROM email_messages m2 LEFT JOIN email_contacts c ON c.id = m2.from_contact_id WHERE m2.thread_id = t.id AND m2.link_id = t.link_id AND NOT (m2.is_draft AND COALESCE((m2.mailbox_state->>'provider_missing')::boolean, false)) ORDER BY (CASE WHEN m2.is_draft = false AND m2.sent_at IS NOT NULL THEN 0 ELSE 1 END) ASC, COALESCE(m2.sent_at, m2.updated_at) DESC NULLS LAST LIMIT 1 ) latest_msg ON true -- LATERAL join for EARLIEST message LEFT JOIN LATERAL ( SELECT m3.subject, m3.sent_at, m3.updated_at FROM email_messages m3 WHERE m3.thread_id = t.id AND m3.link_id = t.link_id AND NOT (m3.is_draft AND COALESCE((m3.mailbox_state->>'provider_missing')::boolean, false)) ORDER BY -- 1. Priority: Non-drafts with valid sent_at come first (0), everything else is fallback (1) (CASE WHEN m3.is_draft = false AND m3.sent_at IS NOT NULL THEN 0 ELSE 1 END) ASC, -- 2. Sort by time (Oldest first) COALESCE(m3.sent_at, m3.updated_at) ASC NULLS LAST LIMIT 1 ) earliest_msg ON true WHERE t.id = ANY($2) AND t.link_id = ANY($1)
